# Paste into AWS CloudShell (console, top bar ">_" icon, region Mumbai). Creates ONE role for the dashboard login function.
# It can only: read/write the iris-dash table, read the one snapshot file, send email from irisforu.com, write its own logs.
aws iam create-role --role-name iris-dash-api --assume-role-policy-document '{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Principal":{"Service":"lambda.amazonaws.com"},"Action":"sts:AssumeRole"}]}' --query Role.Arn --output text
aws iam put-role-policy --role-name iris-dash-api --policy-name iris-dash-api --policy-document '{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Action":["dynamodb:GetItem","dynamodb:PutItem","dynamodb:DeleteItem"],"Resource":"arn:aws:dynamodb:ap-south-1:425434217148:table/iris-dash"},{"Effect":"Allow","Action":"s3:GetObject","Resource":"arn:aws:s3:::iris-dash-data-425434217148/snapshot-v1.json"},{"Effect":"Allow","Action":"ses:SendEmail","Resource":"arn:aws:ses:ap-south-1:425434217148:identity/irisforu.com"},{"Effect":"Allow","Action":["logs:CreateLogGroup","logs:CreateLogStream","logs:PutLogEvents"],"Resource":"arn:aws:logs:ap-south-1:425434217148:log-group:/aws/lambda/iris-dash-api:*"}]}' && echo DONE
